package com.bank.approval.service;

import com.bank.approval.model.ApprovalNode;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Collects every root-to-leaf approval chain whose fees sum to the budget.
public class AllPathsService {
    private static final Logger log = Logger.getLogger(AllPathsService.class.getName());

    public List<List<String>> findAllChainsMatching(ApprovalNode root, BigDecimal budget) {
        List<List<String>> results = new ArrayList<>();
        walk(root, budget, new ArrayList<>(), results);
        log.info(() -> "Found " + results.size() + " matching approval chains");
        return results;
    }

    private void walk(ApprovalNode node, BigDecimal remaining,
                      List<String> currentPath, List<List<String>> results) {
        if (node == null) {
            return;
        }
        // Descend: record this desk on the running path.
        currentPath.add(node.getDeskName());
        BigDecimal afterFee = remaining.subtract(node.getFee());
        log.fine(() -> "At desk " + node.getDeskName() + " remainingAfterFee=" + afterFee);

        if (node.isLeaf() && afterFee.compareTo(BigDecimal.ZERO) == 0) {
            // Store a defensive copy, never the live list.
            results.add(new ArrayList<>(currentPath));
            log.info(() -> "Matched chain: " + currentPath);
        } else {
            walk(node.getLeft(), afterFee, currentPath, results);
            walk(node.getRight(), afterFee, currentPath, results);
        }
        // Backtrack: remove this desk as we climb back up.
        currentPath.remove(currentPath.size() - 1);
    }
}
