package com.bank.approval;

import com.bank.approval.model.ApprovalNode;
import com.bank.approval.service.AllPathsService;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class AllPathsApplication {
    private static final Logger log = Logger.getLogger(AllPathsApplication.class.getName());

    public static void main(String[] args) {
        // Two distinct chains both sum to 400 for Rajesh's transfer.
        ApprovalNode root = new ApprovalNode("Branch", new BigDecimal("100"));
        ApprovalNode regional = new ApprovalNode("Regional", new BigDecimal("250"));
        ApprovalNode audit = new ApprovalNode("Audit", new BigDecimal("200"));
        ApprovalNode signA = new ApprovalNode("SignA", new BigDecimal("50"));
        ApprovalNode signB = new ApprovalNode("SignB", new BigDecimal("100"));

        root.setLeft(regional);
        root.setRight(audit);
        regional.setRight(signA);   // 100+250+50 = 400
        audit.setLeft(signB);       // 100+200+100 = 400

        AllPathsService service = new AllPathsService();
        log.info("Matching chains for Rajesh SAV2001, budget 400: "
                + service.findAllChainsMatching(root, new BigDecimal("400")));
    }
}
